def input_to_array(
    items: dict | npt.ArrayLike,
    n_assets: int,
    fill_value: any,
    dim: int,
    assets_names: np.ndarray | None,
    name: str,
) -> np.ndarray:
    """
    Converts a collection of items, which can be array-like or a dictionary, into a numpy array while ensuring it matches the specified dimensions and shape. It also fills missing values in the dictionary case and verifies the final array's dimensions and shape against expected values.

    Input-Output Arguments
    :param items: dict | npt.ArrayLike. The items to be verified and converted into an array. It can be a dictionary, numpy array, or any array-like structure.
    :param n_assets: int. The expected number of assets, used to verify the shape of the converted array.
    :param fill_value: any. The value used to fill in for missing elements when 'items' is a dictionary and some assets are not present.
    :param dim: int. The dimension of the final array, which can be either 1 or 2.
    :param assets_names: np.ndarray | None. Optional. The names of the assets, used when 'items' is a dictionary to match keys and fill missing values.
    :param name: str. The name of the items, used in error messages for clarity.
    :return: np.ndarray. The converted array with shape (n_assets,) for dim=1 or (n_groups, n_assets) for dim=2, after verifying and converting the input items.
    """
    if isinstance(items, dict):
        if assets_names is None:
            raise ValueError(
                f"`assets_names` cannot be None when `{name}` is a dictionary"
            )
        if dim == 1:
            arr = np.full(n_assets, fill_value)
            for k, value in items.items():
                mask = assets_names == k
                if not np.any(mask):
                    raise ValueError(f"Asset name '{k}' from `{name}` not found")
                arr[mask] = value
        else:
            arr = np.full((len(items), n_assets), fill_value)
            for i, (k, values) in enumerate(items.items()):
                mask = assets_names == k
                if not np.any(mask):
                    raise ValueError(f"Asset name '{k}' from `{name}` not found")
                arr[i, mask] = values
    else:
        arr = np.asarray(items)
        if dim == 1:
            if arr.ndim != 1:
                raise ValueError(
                    f"`{name}` must be a 1D array when `dim=1`, got a {arr.ndim}D array"
                )
            if arr.shape[0] != n_assets:
                raise ValueError(
                    f"`{name}` must be of shape ({n_assets},), got {arr.shape}"
                )
        else:
            if arr.ndim != 2:
                raise ValueError(
                    f"`{name}` must be a 2D array when `dim=2`, got a {arr.ndim}D array"
                )
            if arr.shape[1] != n_assets:
                raise ValueError(
                    f"`{name}` must be of shape (n_groups, {n_assets}), got {arr.shape}"
                )
    return arr
