def safe_interpolate_1d(
    x,
    spline_degree,
    smoothness,
    t_input,
    t_output,
):
  """Interpolates a 1-dimensional signal using spline interpolation."""
  if len(x) == 0:
    return np.zeros_like(t_output, dtype=np.float32)

  k = min(spline_degree, len(x) - 1)
  tck = scipy.interpolate.splrep(t_input, x, s=smoothness, k=k)
  y = scipy.interpolate.splev(t_output, tck)
  return y.astype(x.dtype)
