def _replay_chunks_sampling(
    workers_intervals: Dict[int, List[Any]], indexes: Dict[int, int]
) -> Tuple[Dict[int, int], Dict[int, int]]:
    chunks_index = {}
    new_indexes = {}

    for worker_idx in workers_intervals:
        current_index = indexes[worker_idx]
        intervals = workers_intervals[worker_idx]
        chunk_idx = 0
        remaining = current_index

        for i, interval in enumerate(intervals):
            interval_size = interval[1] - interval[0]
            if remaining >= interval_size:
                remaining -= interval_size
                chunk_idx += 1
            else:
                break

        chunks_index[worker_idx] = chunk_idx
        new_indexes[worker_idx] = remaining

    return chunks_index, new_indexes
