def _replay_sampling(num_samples_yielded: int, batch_size: int, num_workers: int) -> Dict[int, int]:
    samples_per_worker = {}
    base_samples = num_samples_yielded // num_workers
    remainder = num_samples_yielded % num_workers

    for worker_idx in range(num_workers):
        if worker_idx < remainder:
            samples_per_worker[worker_idx] = base_samples + 1
        else:
            samples_per_worker[worker_idx] = base_samples

    return samples_per_worker
