            metric_params_list.append({})
        elif isinstance(metric, dict):
            if 'metric_name' not in metric:
                raise ValueError("Dictionary metric must contain 'metric_name' key")
            metric_names.append(metric['metric_name'])
            params = {k: v for k, v in metric.items() if k != 'metric_name'}
