    def generate(self, model, system_message, prompt, **kwargs):
        """
        This function generates a response from the OpenAI API based on the provided model, system message, prompt, and additional parameters. It handles API key verification, parameter validation, and retries on failure up to 5 times with exponential backoff. It also processes the response to remove any parsing helper tokens before returning the final text.

        Input-Output Arguments
        :param self: OpenAI_API. An instance of the OpenAI_API class.
        :param model: OpenAIConfig, The model configuration to use for generation, including the model name and any parsing helper tokens.
        :param system_message: str, The system message to include in the generation request.
        :param prompt: str, The user prompt to include in the generation request.
        :param **kwargs: dict, Additional optional parameters for generation such as temperature, top_p, frequency_penalty, presence_penalty, and max_new_tokens.
        :return: str, The generated text response from the OpenAI API after removing any parsing helper tokens.
        """
        self.check_api_key()

        # Filter kwargs to only include valid generation parameters
        generation_params = {k: v for k, v in kwargs.items() if k in LLM_GENERATION_PARAMETERS}

        max_retries = 5
        retry_delay = 1

        for attempt in range(max_retries):
            try:
                response = self.client.chat.completions.create(
                    model=model.model_name,
                    messages=[
                        {"role": "system", "content": system_message},
                        {"role": "user", "content": prompt}
                    ],
                    **generation_params
                )

                if response.choices and len(response.choices) > 0:
                    generated_text = response.choices[0].message.content
                    # Remove parsing helper tokens if they exist
                    if hasattr(model, 'parsing_helper_tokens') and model.parsing_helper_tokens:
                        for token in model.parsing_helper_tokens:
                            generated_text = generated_text.replace(token, '')
                    return generated_text.strip()
                else:
                    raise ValueError("No choices in response")

            except Exception as e:
                if attempt == max_retries - 1:
                    raise e
                time.sleep(retry_delay * (2 ** attempt))
                continue

        return None
