def assert_instances_allclose(input, other, *, rtol=1e-5, msg="", size_as_tensor=False):
    if not size_as_tensor:
        assert input.image_size == other.image_size, f"{msg} image_size differs! {input.image_size} vs {other.image_size}"
    else:
        assert torch.allclose(
            torch.tensor(input.image_size), torch.tensor(other.image_size)
        ), f"{msg} image_size differs! {input.image_size} vs {other.image_size}"

    fields = set(input._fields.keys()).union(other._fields.keys())
    for field in fields:
        val1 = input.get(field, None)
        val2 = other.get(field, None)
        if val1 is None or val2 is None:
            assert val1 is None and val2 is None, f"{msg} Field {field} differs (None vs not None)"
            continue

        if isinstance(val1, Boxes) and isinstance(val2, Boxes):
            assert torch.allclose(
                val1.tensor, val2.tensor, rtol=rtol
            ), f"{msg} Field {field} differs!"
        elif isinstance(val1, ROIMasks) and isinstance(val2, ROIMasks):
            assert len(val1.tensor) == len(val2.tensor), f"{msg} Field {field} length differs!"
            assert torch.allclose(
                val1.tensor, val2.tensor, rtol=rtol
            ), f"{msg} Field {field} differs!"
        elif isinstance(val1, torch.Tensor) and isinstance(val2, torch.Tensor):
            assert torch.allclose(
                val1, val2, rtol=rtol
            ), f"{msg} Field {field} differs!"
        else:
            assert val1 == val2, f"{msg} Field {field} differs! {val1} vs {val2}"
