def topk_search(model: Model, prefix: str, idx: int, k=1, high=40):
    # get raw topk, could be done outside and passed in
    num_calls = k
    if model.argmax(prefix) == idx:
        return 0, num_calls

    logit_bias = {idx: high}
    while True:
        topk_words = model.topk(prefix, logit_bias)
        num_calls += k
        if idx in topk_words:
            if topk_words[idx] == max(topk_words.values()):
                break
            else:
                logit_bias[idx] *= 2
        else:
            logit_bias[idx] *= 2

    return -logit_bias[idx], num_calls
