    def positions(self, token: str, key=None) -> List[np.ndarray]:
        """
        This function retrieves and returns a list of numpy arrays representing the positions of a given term within documents. If a specific document key is provided, it returns the positions for that document only; otherwise, it returns positions across all documents.

