def parse_min_should_match(num_clauses: int, spec: str) -> int:
    """
    This function parses the "min should match" specification (commonly referred to as 'mm' spec) from Solr's search engine configuration and calculates the minimum number of clauses that must match based on the given specification and the total number of clauses. It supports both absolute and percentage-based specifications, as well as conditional specifications using '<'.

    Input-Output Arguments
    :param num_clauses: int, the total number of clauses in the query.
    :param spec: str, the 'min should match' specification as a string, which can include absolute numbers, percentages, and conditional expressions.
    :return: int, the calculated minimum number of clauses that must match according to the 'mm' spec.
    """
    if not spec:
        return 1

    if spec.isdigit():
        return min(int(spec), num_clauses)

    if spec.endswith('%'):
        percentage = int(spec[:-1])
        if percentage < 0:
            return max(1, num_clauses + (num_clauses * percentage // 100))
        else:
            return min(num_clauses, max(1, (num_clauses * percentage + 99) // 100))

    if '<' in spec:
        parts = spec.split('<')
        if len(parts) != 2:
            return 1
        threshold = int(parts[0])
        if num_clauses < threshold:
            return int(parts[1])
        else:
            return num_clauses

    return 1
```

