    def phrase_freq(self, tokens: List[str], slop=1) -> np.ndarray:
        """
        This function calculates the frequency of a phrase within a SearchArray instance based on the provided tokens and slop. If the slop is 1 and all tokens are unique, it attempts to directly calculate the phrase frequencies using the positions of terms. If the slop is not 1 or tokens are not unique, it delegates the calculation to another method that handles different slops or non-unique tokens.

        Input-Output Arguments
        :param self: SearchArray. An instance of the SearchArray class.
        :param tokens: List[str]. A list of tokens (words) for which the phrase frequency is to be calculated.
        :param slop: int, optional. The maximum distance between tokens in the phrase. Defaults to 1, meaning tokens must be adjacent.
        :return: np.ndarray. An array of phrase frequencies corresponding to the tokens in the SearchArray instance.
        """
        if len(tokens) < 2:
            raise ValueError("Must have at least two terms")

        if slop == 1 and len(tokens) == len(set(tokens)):
            try:
                term_ids = [self.term_dict.get_term_id(token) for token in tokens]
                phrase_freqs = np.zeros(len(self), dtype=int)
                if self.term_mat.subset:
                    doc_ids = self.term_mat.rows
                    phrase_freqs = self.posns.phrase_freqs(term_ids, phrase_freqs, doc_ids)
                else:
                    doc_ids = np.arange(len(self))
                    phrase_freqs = self.posns.phrase_freqs(term_ids, phrase_freqs, doc_ids)
                return phrase_freqs
            except TermMissingError:
                return np.zeros(len(self), dtype=int)
        else:
            return self.phrase_freq_every_diff(tokens, slop=slop)
